// Leaf Ranger sounds: the draw, bow releases, arrows whistling, single arrows landing, the volley's whoosh as it
// comes down, and its landing. The events below call runtimeScene.__lrSfx.play(kind, gain, delay) or .spread(n, gap).
// A set without a kind just stays silent there.
// USE picks the set:
//   "pack" - the user's arrow sound pack, cut into variations by tools/fx/arrows_pack.js (assets/Sfx/arrows), with
//            our synthesized whoosh for the falling volley.
//   "own"  - synthesized by tools/fx/bow.js.
// Each set has its own volumes, as their levels differ.
const USE = "pack";
const SETS = {"own":{"bow":["assets/Sfx/arrows/synth/bow_release_1.wav","assets/Sfx/arrows/synth/bow_release_2.wav","assets/Sfx/arrows/synth/bow_release_3.wav","assets/Sfx/arrows/synth/bow_release_4.wav","assets/Sfx/arrows/synth/bow_release_5.wav"],"fall":["assets/Sfx/arrows/synth/volley_fall.wav"],"impact":["assets/Sfx/arrows/synth/volley_impact_1.wav","assets/Sfx/arrows/synth/volley_impact_2.wav","assets/Sfx/arrows/synth/volley_impact_3.wav"],"vol":{"bow":85,"fall":55,"impact":70}},"pack":{"draw":["assets/Sfx/arrows/draw_1.wav","assets/Sfx/arrows/draw_2.wav","assets/Sfx/arrows/draw_3.wav"],"bow":["assets/Sfx/arrows/release_1.wav","assets/Sfx/arrows/release_2.wav","assets/Sfx/arrows/release_3.wav","assets/Sfx/arrows/release_4.wav"],"whistle":["assets/Sfx/arrows/whistle_1.wav","assets/Sfx/arrows/whistle_2.wav","assets/Sfx/arrows/whistle_3.wav"],"land":["assets/Sfx/arrows/land_1.wav","assets/Sfx/arrows/land_2.wav","assets/Sfx/arrows/land_3.wav","assets/Sfx/arrows/land_4.wav","assets/Sfx/arrows/land_5.wav"],"fall":["assets/Sfx/arrows/synth/volley_fall.wav"],"impact":["assets/Sfx/arrows/rain_1.wav","assets/Sfx/arrows/rain_2.wav","assets/Sfx/arrows/rain_3.wav","assets/Sfx/arrows/rain_4.wav"],"vol":{"draw":45,"bow":70,"whistle":45,"land":50,"fall":55,"impact":65}}};
// Shortest time between two sounds of a kind (s): the Overgrowth wave lands several rains at once.
const COOLDOWN = { impact: 0.15, land: 0.06, whistle: 0.05 };
const S = runtimeScene.__lrSfx || (runtimeScene.__lrSfx = { last: {} });
S.set = SETS[USE];
if (!S.play) {
  // One sound of a kind, picked at random, at a slightly random pitch so repeats don't sound identical.
  S.play = function (kind, gain, delay) {
    const list = S.set[kind]; if (!list) return;
    const go = function () {
      const now = Date.now() / 1000; if (COOLDOWN[kind] && now - (S.last[kind] || 0) < COOLDOWN[kind]) return; S.last[kind] = now;
      runtimeScene.getGame().getSoundManager().playSound(list[Math.floor(Math.random() * list.length)], false, S.set.vol[kind] * (gain || 1), 0.94 + Math.random() * 0.12);
    };
    if (delay > 0) setTimeout(go, delay * 1000); else go();
  };
  // n releases, gap seconds apart, the later ones a little quieter.
  S.spread = function (n, gap) { for (let k = 0; k < n; k++) S.play("bow", k ? 0.7 : 1, k * gap); };
}
